    const slide=()=>{$('home-slide').innerHTML=`<h3>${slides[homeSlide][0]}</h3><p>${slides[homeSlide][1]}</p><p>예제 캠페인 기간: 2024-03-01 ~ 2024-03-31</p><a href="#services">캠페인 관련 서비스</a>`;$('slide-count').textContent=`${homeSlide+1} / ${slides.length}`;};
